"""Build company-specific skills orientation and quizzes; never publish or change billing.

Private manuscript retained alongside editions. Public evidence has one editorial
source in frontend/src/content; this build embeds that reviewed text in each guide.
"""
import hashlib
import json
import subprocess
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'content/skill-development-guides'
OUT.mkdir(parents=True, exist_ok=True)
EVIDENCE = json.loads((ROOT.parents[1] / 'frontend/src/content/learning-support-evidence.json').read_text())
KEY = 'skill-development-guide'
def link(url, title): return f'<a href="{escape(url, quote=True)}">{escape(title)}</a>'
def jump(slug, title): return link(f'#{KEY}-{slug}', title)
def build(tenant):
    name = 'ITSCO' if tenant == 'itsco' else 'Next Level Up'
    sections = []
    def add(slug, title, body, parent=None):
        sections.append(dict(slug=slug, title=title, body_html=body, parent_slug=parent,
                             sort_order=len(sections), content_status='ready', source_page=None))
    add('skills-orientation', 'Start here · Skills, connection and practice', '''
<p>Help children practice skills they can use: asking for support, navigating frustration, working with others and returning to a meaningful task. Start with connection, clear expectations and respect for each child’s development, culture and communication.</p>
<p><strong>This guide is familiarization, not authorization to practice.</strong> Reading, asking questions or passing the knowledge check does not establish competence, certify a technique or authorize a group, diagnosis, treatment or billing code. Approved activities require an appropriate role, relevant education and training, observed competence and the required oversight.</p>
<p>Use the current company Workplace Handbook, Provider’s Guide and Care Approaches &amp; Practice Guide alongside this document. Bring conflicting instructions to the clinical lead before proceeding; this guide does not override current restrictions.</p>
<p>Find this guide in the Library, onboarding, My Learning/Plotline and on-demand learning. Required onboarding and supervisor- or administrator-assigned training use the app’s paid-time workflow. Optional review and retakes are on your own time. Record assigned learning time in the app; do not create an outside time log.</p>
<p><a href="/workplace-handbook">Workplace Handbook</a> · <a href="/library?companyDocument=provider-guide">Provider’s Guide</a> · <a href="/library?companyDocument=counseling-guide#counseling-guide-facilitator-scope">Care Approaches &amp; Practice Guide · Facilitator scope</a></p>''')
    if tenant == 'itsco':
        add('program-boundaries', 'ITSCO · Skill Builders and current authorization', '''
<p>Skill Builders supports interpersonal skills, personal development and emotional well-being through approved group activities. The supplied curriculum describes twelve 90-minute sessions with two to four activities per session. This is a curriculum framework, not an automatic schedule, clinical dose or billable duration for every participant.</p>
<p><strong>The current group moratorium still applies.</strong> Approved Skill Builders programming may continue within its existing written authorization. Other groups require an express written exception before advertising, enrolling or scheduling. This guide does not open a new group. H2014 is limited to Skill Builders with express written approval and is not approved for individual services. A saved service/payroll code is not approval to use it.</p>
<p>Before delivery, verify the actual program approval, participant eligibility, plan, staffing, supervision, location, attendance requirements, payer rules and all work-time arrangements. If attendance or circumstances fall outside the approval, consult leadership and billing; do not invent a minimum group size, convert the visit to an insured individual service or bill absent participants.</p>
<p><a href="/workplace-handbook#handbook-group-services-moratorium-and-exceptions">Handbook · Group services, moratorium and exceptions</a></p>''')
        add('service-separation', 'Actual activities, time and eligible services', '''
<p>Use the code and format approved for the actual service. Ordinary recreation, a curriculum activity or scheduled attendance alone does not establish clinical necessity or reimbursement. Record each participant’s actual service, response, attendance and service time in the app; document preparation and other work through the appropriate time workflow.</p>
<p>Never fill in a scheduled 90 minutes when fewer minutes occurred, bill absent participants or use H0004 as a replacement group code. H0004 is an individual service subject to the current plan, scope and payer requirements. Have billing resolve uncertain codes before a claim is submitted. Claim eligibility and compensable work time are different questions.</p>''')
    else:
        add('program-boundaries', 'NLU · Skills during the learning process', '''
<p>Next Level Up’s Therapy + Tutoring, also called the Cognitive &amp; Emotional Enrichment Program, coordinates academic instruction, emotional skill development and counseling when appropriate. NLU does not operate an ITSCO Skill Builders program or provide school-based services. This edition applies to approved NLU locations or approved virtual services.</p>
<p>The focus is the student who becomes overwhelmed, discouraged, frustrated or dysregulated while attempting academic work. A coordinated plan can include practicing a help request, taking a supported break, handling a mistake, communicating with peers and returning to an achievable learning step. Emotional support does not replace instruction when the student needs help learning the material.</p>
<p><strong>H2014 is permitted for eligible individual and small-group skills services within Therapy + Tutoring.</strong> Small groups are encouraged; scheduling three clients is a planning preference, and two or more attending constitute a group. With only one attending, an individual H2014 service may proceed when the actual service, plan, provider, authorization and payer requirements permit it. Record the actual format and attendance; never bill absent participants. If those requirements are not met, consult leadership and billing about rescheduling or a separately agreed, permitted self-pay service.</p>
<p>The employee’s approved category and level Direct Care rate applies to eligible individual H2014 service and the base for group service. Pay the group base once, with an additional $5 per actual attendee for a group of two or more; one individual attendee does not qualify for the group supplement. Follow the current handbook for unit equivalents and indirect-time treatment.</p>
<p>Program permission is not proof of payer coverage. Check the approved plan, provider, code, authorizations, setting, funding, current billing-provider enrollment and payer edits for the actual service. Other group codes remain under the moratorium unless an express written exception applies. The ITSCO twelve-session, 90-minute curriculum does not prescribe NLU’s format.</p>
<p><a href="/workplace-handbook#handbook-therapy-plus-tutoring-program">Handbook · Therapy + Tutoring</a> · <a href="/workplace-handbook#handbook-group-services-moratorium-and-exceptions">Handbook · Group attendance and authorization</a></p>''')
        add('service-separation', 'T+T · Separate tutoring, skills services and counseling', '''
<p>H2014 skills training may be delivered individually or in an eligible small group within the approved NLU program. It must address a covered behavioral health need and meet the applicable clinical plan, scope, supervision, documentation and payer requirements. Ordinary academic tutoring does not become H2014 merely because the services are coordinated. H0004 describes individual behavioral health counseling/therapy; it is not a default code for a skills group or tutoring. The January 2026 HCPF manual is a dated reference; billing must confirm the rules and payer arrangement for the service date.</p>
<p>An approved individual blended visit may include up to 30 minutes of self-pay tutoring and 30 minutes of H0004 counseling. Record the literal, non-overlapping portions actually delivered, with distinct academic and clinical goals, provider roles, content, response and time. A single coordinated appointment does not make an hour of tutoring into therapy, guarantee two claim units or permit double-counting minutes. Use the app’s applicable service records and have billing review the output; this guide does not enable an automatic split claim.</p>
<p>Tutoring remains self-pay and separate from the clinical claim. Confirm the agreement, member-billing rules, clinical assessment/plan, medical necessity, coverage, eligibility, supervision and authorizations before delivery. If one client attends a planned skills group, document eligible individual H2014 service only when actually delivered and permitted. Do not relabel it as counseling to preserve a payment. Any counseling must be independently appropriate and authorized.</p>
<p>A shared context summary may reduce repetition where the app supports it, but each service still needs its own identifiable record of what actually occurred. Never copy a generic success statement across participants or services.</p>
<p><a href="https://hcpf.colorado.gov/sites/hcpf/files/January%202026%20SBHS%20Billing%20Manual1.13.26.pdf">HCPF · January 2026 SBHS manual, H0004</a> · <a href="https://hcpf.colorado.gov/sbhs-billing-manual">Current manual index</a></p>''')
    add('facilitator-scope', 'Facilitator scope and licensed oversight', '''
<p>Bachelor’s-level staff in this role introduce themselves as <strong>facilitators</strong>, not counselors or therapists. Work only within your education, relevant training, demonstrated skills and approved responsibilities. Support approved low-acuity activities and bring emerging needs to the responsible clinician.</p>
<p>Facilitators do not independently diagnose, choose a primary diagnosis or initiate diagnosis-targeted treatment. Obtain express, documented approval from the responsible, appropriately qualified, fully licensed clinician before diagnosis-targeted work. Approval cannot expand lawful scope, payer eligibility or competence. An existing diagnosis is not automatic permission to treat it.</p>
<p>All facilitator clinical work requires oversight by an appropriately qualified, fully licensed provider with at least two years in the field, plus applicable stricter board and payer requirements. Confirm the supervisor, backup, approved plan and consultation arrangements before a session. A tutor does not become a clinical facilitator merely by learning supportive communication.</p>
<p>Examples in this guide are for supervised discussion and rehearsal. They do not qualify someone to deliver CBT, exposure therapy, trauma processing, behavior analysis, restraint or crisis assessment. Use the Care Approaches &amp; Practice Guide for the fuller scope and H0004 orientation; the actual client plan and credential requirements still control.</p>''')
    add('skill-domains', 'Three connected skill domains', '''
<h3>Interpersonal skills</h3><p>Collaboration, trust, respectful disagreement, active listening, communication, interpreting cues tentatively and solving shared problems. Check the child’s meaning rather than assuming eye contact or body language means the same thing across people and cultures.</p>
<h3>Personal development</h3><p>Identifying strengths, choosing meaningful goals, reflecting on progress, exploring values and practicing self-advocacy. Gratitude is an optional reflection, never an instruction to dismiss hardship or replace an unwanted feeling.</p>
<h3>Emotional well-being</h3><p>Naming feelings, noticing early signs of overwhelm, rehearsing approved coping options, tolerating manageable frustration and asking for help. Exploring alternative explanations is different from diagnosing a “thinking trap” or conducting cognitive therapy without the necessary competence and authorization.</p>
<p>Choose a small number of observable skills appropriate to the participant’s plan. Do not promise mastery or resilience simply because the curriculum has been completed.</p>''')
    add('rapport', 'Connection before correction', '''
<p>Use language that fits the child’s development and communication. Offer activities connected to their interests, listen without rushing and reflect tentatively: “That felt frustrating—is that right?” Invite correction. Explain your role and follow through on commitments.</p>
<p>Do not require eye contact, stillness, personal disclosure or cheerful participation as proof of engagement. Offer accessible ways to respond: words, drawing, pointing, supported communication or observing. Ask about sensory and access needs instead of treating a different communication style as defiance.</p>
<p>A warm introduction might be: “I’m a facilitator. We can practice asking for help or taking a break. You can tell me when something isn’t working.” Explain the actual oversight and purpose without claiming a therapy credential.</p>''')
    add('predictable-routines', 'Predictable routines and transitions', '''
<p>Show the sequence before starting: welcome, skill example, supported practice, reflection and close. Use a simple visual schedule, advance transition cues and choices that are genuinely available. Adjust pace and task size to the child rather than insisting everyone finishes at the same rate.</p>
<p>State boundaries in concrete, respectful language: “We keep people safe and ask before taking materials.” Model the help request or turn-taking action. Make movement, communication aids and needed breaks available; they are not privileges to earn.</p>
<p>Behavior may convey unmet needs, confusion, distress or a skill mismatch, but it does not reveal a single cause. Record observable events and ask what might help. Avoid labeling a child “attention seeking,” “noncompliant” or manipulative based only on an interruption or refusal.</p>''')
    add('co-regulation', 'Responding to frustration and dysregulation', '''
<p>First attend to immediate safety. Use a calm voice, reduce unnecessary demands and language, acknowledge distress and offer space while maintaining the agreed safe supervision. “Would you like a quieter place with me nearby, or help with one small step?” Do not crowd, force eye contact or insist on a breathing exercise.</p>
<p>Offer a choice to pause, observe or ask for help within the approved plan. Needed breaks are supportive, not punishment. When the child is ready, invite a manageable return; do not require a child to suppress distress to gain access to help or rejoin.</p>
<p>Stop an activity that worsens distress or exceeds your role. Contact the qualified clinical lead when the need is beyond approved low-acuity support. These examples are not a crisis protocol or permission for physical intervention. Use the emergency procedures for immediate danger.</p>''')
    add('encouragement', 'Encouragement that supports agency', '''
<p>Notice a useful action without judging the child: “You asked for help when the task got hard,” or “You tried a smaller step.” Acknowledge effort, access needs and choice rather than rewarding silence, forced eye contact or hiding emotion.</p>
<p>Offer respectful, individualized feedback; some children prefer private acknowledgment. Avoid comparisons, public behavior rankings or promises that everyone will feel better. Ask whether the feedback is useful.</p>
<p>Use a token or reward system only when the responsible clinician has approved the purpose, fit and safeguards and staff have the required competence. Never withhold basic needs, communication tools, access supports or needed breaks. Do not improvise a behavioral treatment protocol from the examples in the original manual.</p>''')
    add('practice-examples', 'Practice examples · Ask, pause, try a next step', '''
<p>These are optional illustrations for discussion with the supervisor, not treatment scripts or a standardized curriculum. Select and adapt only within the approved plan.</p>
<table><thead><tr><th>Moment</th><th>Possible supported practice</th><th>What to observe</th></tr></thead><tbody>
<tr><td>A task feels too hard</td><td>Model “Can you help me with the first step?” Offer a smaller accessible task.</td><td>How help was requested, support needed and the child’s response.</td></tr>
<tr><td>A mistake brings frustration</td><td>Acknowledge the feeling. Offer a pause or one retry together without demanding a positive thought.</td><td>Whether the option helped; stop if distress grows.</td></tr>
<tr><td>Two peers need the same material</td><td>Practice requesting, taking turns or choosing another material.</td><td>Actual communication and adult prompts, not an assumed motive.</td></tr>
<tr><td>A child does not want to join</td><td>Offer observing, a quieter role or another accessible way to participate.</td><td>Expressed preferences and barriers; discuss persistent difficulty with the lead.</td></tr>
</tbody></table>''')
    if tenant == 'nlu':
        add('learning-moments', 'NLU · Practice where learning becomes difficult', '''
<p>A student stares at a math problem and pushes the paper away. Check whether they understand the task and can access the materials. Do not assume a behavioral problem when instruction, language support, vision, sensory access or a smaller task might be needed. Bring assessment needs to the appropriate professional.</p>
<ol><li><strong>Notice:</strong> describe the observable difficulty and ask what the student is experiencing.</li><li><strong>Support:</strong> offer an approved help request, manageable pause or quiet choice.</li><li><strong>Practice:</strong> rehearse a specific skill, such as asking a peer to wait while finding an answer.</li><li><strong>Return:</strong> invite one achievable academic step when ready, with appropriate instruction.</li><li><strong>Review:</strong> ask what helped; document the actual support and response in the app.</li></ol>
<p>In an approved small group, students might practice asking for clarification, responding to a mistake or negotiating roles in a shared learning activity. Protect each participant’s privacy and individual plan. Academic completion alone does not establish that a clinical service occurred.</p>
<p>A clinician directs clinical goals and authorized interventions; tutoring addresses academic instruction. Support should be coordinated with consent, while the service portions and their records remain identifiable.</p>''')
    add('professional-conduct', 'Professionalism, inclusion and boundaries', '''
<p>Keep the focus on participants, not your personal beliefs or experiences. Avoid imposing values, debating private disagreements in front of a group or using a child to meet your need for reassurance. Any self-disclosure must be brief, relevant and appropriate to the approved purpose.</p>
<p>Respect language, identity, disability and cultural differences. Address harmful conduct without humiliating a participant or assuming intent. Use supervision to reflect on uncertainty.</p>
<p>Raise ordinary professional disagreements privately through the app’s appropriate internal workflow. Report harassment, discrimination and safety concerns through the required channels; do not make private confrontation or informal resolution a prerequisite. Keep sensitive records in authorized app areas, not personal files.</p>''')
    add('group-privacy', 'Privacy and consent in a group', '''
<p>Verify consent, legal decision-making authority and permitted communication before participation. Explain the purpose, roles, privacy expectations and applicable limits in accessible language. Staff must protect information, but cannot guarantee that other participants will keep everything private. Do not promise absolute group confidentiality.</p>
<p>Invite discussion without requiring personal trauma stories or identifying details. Do not name another participant in a family update or copy one child’s identifying information into another child’s record. Share with authorized people only, following the applicable consent, privacy and reporting procedures.</p>
<p>Use approved app records and access controls for notes, attendance, plans, supervision and internal incident records. Route access or correction requests through the agency’s established privacy process. Do not enter client names or case details into this guide’s question box. The Q&amp;A explains the guide and does not review individual cases.</p>''')
    add('safety-and-emergencies', 'Safety, urgent concerns and leaving the area', (
'''<p>For a school assignment, know the site’s emergency procedure, approved space, release/pickup arrangements, school contact and backup before arrival. Review these together with ITSCO’s current school and workplace procedures. School staff coordination does not replace your own emergency or reporting responsibilities.</p><p><a href="/library?companyDocument=school-practice-guide">ITSCO School Practice Guide</a></p>'''
        if tenant == 'itsco' else
'''<p>Before an NLU session, know the approved location’s emergency procedure, exits, safe supervision, release/pickup arrangements and clinical backup. For virtual work, follow the approved location/contact and emergency plan. Do not substitute school-security procedures for NLU’s actual setting.</p>''') + '''
<p>For immediate danger or a medical emergency, use emergency services, including 911 when appropriate, and promptly contact qualified clinical support. Follow the applicable mandatory-reporting procedure; an app incident report or supervisor notification does not replace a required external report or emergency call.</p>
<p>If a child tries to leave the supervised area, activate the site’s missing-child/elopement response and get help while protecting the other participants. Do not abandon the group, improvise restraint or use this guide as physical-intervention training. Do not wait for the child to cross a property boundary before responding to danger.</p>
<p>Persistent or increasing distress, suspected abuse, self-harm concerns or needs beyond the approved plan require prompt qualified review. Do not make an independent diagnosis or risk determination to keep a session running. Record facts and actions afterward in the appropriate app record without delaying the response.</p>''')
    add('planning-and-notes', 'Plan, observe and document the actual service', '''
<p>The responsible qualified clinician determines clinical assessment, diagnosis and treatment planning. Facilitators contribute observations and implement specifically approved activities; they do not independently select a diagnosis or treatment protocol. Agree on a meaningful, observable goal and what support is appropriate.</p>
<p>Document in the app: actual attendance and service/time, approved goal, activity delivered, support or prompts, the participant’s report where relevant, observable response, difficulties or adverse effects, consultation and next step. Record consent accurately; do not prefill “consented and participated” when that did not occur.</p>
<p>Example of an observation: “After a prompt, the participant asked for help with the first step and chose to try it with support.” Describe what happened without inventing a diagnosis, progress, medical necessity or a positive outcome. Do not write notes primarily to justify reimbursement.</p>
<p>Individual records must distinguish each participant’s service and response. Coordinate only permitted information with the family and care team. Record preparation, supervision and other work in the app’s appropriate time workflow; these minutes do not automatically become direct service time.</p>''')
    add('precepting', 'Observation → assistance → observed facilitation', '''
<ol><li><strong>Observe:</strong> with appropriate consent and access, watch an approved, experienced facilitator. Discuss rapport, access needs, transitions, safety, privacy and how the plan is followed.</li><li><strong>Assist:</strong> rehearse an approved portion under the assigned lead’s supervision. Receive feedback and demonstrate the specific skills before taking on more responsibility.</li><li><strong>Facilitate under observation:</strong> lead only the approved activities while a qualified lead observes and supports. This stage is not independent clinical practice.</li></ol>
<p>The responsible clinical supervisor must document the competence observed, authorized activities, limits, ongoing oversight and review date in the app. A quiz pass or attendance at precepting does not automatically complete this sign-off. Student agreements and supervision requirements continue to apply.</p>
<p>Use synthetic scenarios to rehearse a help request, a peer disagreement, refusal, rising distress and an urgent handoff. Reflect on what you noticed, how the child’s choice was respected and when you would consult. Continue supervision and review when a setting, role or client need changes.</p>''')
    add('progress-review', 'What progress looks like', '''
<p>Agree with the child, family and qualified team on useful goals and review points. Examples include asking for help with fewer prompts, identifying a preferred support, returning to an accessible task when ready or communicating a disagreement respectfully. Record the context and support required, not just whether work was completed.</p>
<p>For academic goals, use the appropriate instructional measure. For clinical goals, use the clinician’s plan and suitable authorized outcome measures. A quiet child is not necessarily a regulated child, and a completed worksheet does not prove improved mental health.</p>
<p>Review lack of benefit, increasing distress, attendance barriers and family feedback. Adapt or refer through the responsible team rather than increasing pressure to comply. Individual progress records help care decisions; they do not by themselves prove the program caused an improvement or justify a public effectiveness claim.</p>''')
    add('research-and-rationale', 'Research · Why support skills and learning together?', '''
<p>Our rationale is to pair appropriate instruction with support for the emotional and interpersonal demands of learning. This is an application of evidence about related components, not proof that a particular combination, schedule or service code produces a promised outcome.</p>''' + '<p>'+escape(EVIDENCE['context'] if tenant == 'nlu' else EVIDENCE['context'].replace('NLU’s Therapy + Tutoring program', 'ITSCO’s Skill Builders program'))+'</p>' + ''.join(
        '<h3>'+escape(s['heading'])+'</h3><p>'+escape(s['finding'])+'</p><p>'+escape(s['limit'])+'</p><p>'+link(s['url'],s['citation'])+'</p>' for s in EVIDENCE['studies']) +
        '<p>Evidence reviewed October 10, 2026. These are research summaries, not copied instruments, curricula or permission to deliver a clinical technique. Discuss relevance to the actual child, program intensity and setting in supervision.</p>')
    add('quick-reference', 'Before, during and after a session', '''
<h3>Before</h3><p>Confirm program and case approval, your scope, qualified oversight, participant consent, actual setting, attendance rules, plan, access needs, supplies and emergency contacts. Select an achievable approved practice activity.</p>
<h3>During</h3><p>Connect, explain the routine, offer accessible choices, model the skill and notice the response. Maintain privacy and safe supervision. Pause or escalate when distress or need exceeds the plan.</p>
<h3>After</h3><p>Document actual services, time, response and next steps in the app. Share permitted information with the team and obtain supervision. Use observations to guide the next approved session.</p>''' + '<p>'+jump('program-boundaries', 'Your company’s program rules')+' · '+jump('facilitator-scope','Scope and oversight')+' · '+jump('safety-and-emergencies','Safety procedures')+'</p>')
    sanitized = subprocess.run(['node','--input-type=module','-e', "import fs from 'node:fs'; import {cleanHandbookHtml} from './backend/src/services/workplaceHandbookContent.js'; const s=JSON.parse(fs.readFileSync(0,'utf8')); process.stdout.write(JSON.stringify(s.map(x=>({...x,body_html:cleanHandbookHtml(x.body_html)}))));"], cwd=ROOT.parents[1], input=json.dumps(sections), text=True, capture_output=True, check=True)
    sections = json.loads(sanitized.stdout)
    source = dict(documentKey=KEY, title='Skill Development & Learning Guide', organization=name,
                  sourceDate='2026-10-10', edition='Skills in practice · Familiarization', learningPurpose='orientation', sections=sections)
    (OUT/f'{tenant}.json').write_text(json.dumps(source, ensure_ascii=False, indent=2)+'\n')
    qs = [
        ('orientation','Does completing this guide authorize you to run a group independently?', ['Yes, after passing the quiz.','No. Program approval, appropriate scope, observed competence and required oversight are still necessary.','Yes, if three children are scheduled.'],1,'Completion records familiarization, not clinical competence or program authorization.','skills-orientation'),
        ('program','Only one client attends an NLU skills group. What should happen?' if tenant == 'nlu' else 'May you start a new ITSCO group after reading this curriculum?', ['Bill the scheduled group and its supplement.','Bill individual H2014 automatically, regardless of the plan or payer.','Provide and document individual H2014 only if the actual service, plan, provider, authorization and payer requirements permit it; otherwise consult leadership and billing.'] if tenant == 'nlu' else ['Yes, the twelve-session outline is approval.','Only within an existing written authorization or express written exception under the group policy.','Yes, if a code is in payroll.'],2 if tenant=='nlu' else 1,'NLU permits eligible individual H2014 within Therapy + Tutoring. Group billing and the $5-per-attendee supplement require an actual group of two or more; absent clients are not billed.' if tenant=='nlu' else 'The current group moratorium and written approval rules remain in force.','program-boundaries'),
        ('scope','A family wants a facilitator to treat a primary diagnosis. What is needed?', ['A completed guide quiz.','Express documented approval from the responsible qualified licensed clinician, plus lawful scope, competence, an appropriate plan and required oversight.','Permission from any coworker.'],1,'Facilitators do not independently diagnose or initiate diagnosis-targeted care. Approval does not expand scope.','facilitator-scope'),
        ('support','A child pushes materials away and looks overwhelmed. What fits this guide?', ['Demand eye contact and participation.','Remove breaks until the child cooperates.','Check safety, acknowledge distress and offer an accessible choice or supported pause within the approved plan.'],2,'Use calm support and safe supervision; escalate needs beyond the approved role.','co-regulation'),
        ('privacy','What should you explain about group privacy?', ['Staff protect information, but cannot guarantee other participants will keep it private.','Everything said is guaranteed confidential.','Families may receive the other participants’ notes.'],0,'Explain realistic privacy expectations and limits, and keep each participant’s identifying information protected.','group-privacy'),
        ('services','How should an approved blended NLU appointment be recorded?' if tenant=='nlu' else 'What duration belongs in a clinical service record?', ['As one hour of insured counseling.','As the actual, non-overlapping tutoring and clinical portions with distinct content, time and appropriate billing review.','Use the same clinical note and minutes twice.'] if tenant=='nlu' else ['The scheduled 90 minutes for every attendee.','The actual eligible service and time delivered to that participant.','The preparation time plus the full scheduled session.'],1,'A coordinated booking does not combine funding rules or allow double-counting.' if tenant=='nlu' else 'The curriculum schedule is not evidence of delivered service or billable time.','service-separation'),
        ('precepting','What follows observation and supervised assistance?', ['Independent practice authorized by quiz completion.','Observed facilitation of approved activities, followed by documented supervisor review of competence and ongoing oversight.','Permission to deliver any technique in the manual.'],1,'Precepting is staged and supervised. Clinical sign-off is separate from the knowledge check.','precepting'),
        ('evidence','What can we say about the research cited here?', ['It guarantees grades will improve in this program.','It proves a weekly blended visit matches intensive tutoring trials.','It supports related components, but did not test this agency’s specific program.'],2,'Apply evidence with attention to population, intensity and setting; do not promise program-specific outcomes.','research-and-rationale')]
    reading = ['skills-orientation','program-boundaries','facilitator-scope','rapport','co-regulation','group-privacy','safety-and-emergencies','service-separation','planning-and-notes','precepting','research-and-rationale']
    if tenant == 'nlu': reading.insert(5,'learning-moments')
    hashes = {s['slug']:hashlib.sha256(s['body_html'].encode()).hexdigest() for s in sections if s['slug'] in reading}
    definition = dict(documentKey=KEY, tenants=[tenant], onboardingAudience='clinical',
                      title='Skill Development & Learning Guide · Read & practice',
                      description=('ITSCO Skill Builders orientation, current group approvals and supervised practice.' if tenant=='itsco' else 'NLU Therapy + Tutoring: skills during learning, group attendance, service separation and supervised practice.'),
                      requiredSections=reading, questions=[dict(zip(['id','prompt','options','correctAnswer','explanation','sourceSlug'],q)) for q in qs],
                      passingScore=100, sectionHashes=hashes)
    (ROOT/f'content/document-training/skill-development-guide-{tenant}.json').write_text(json.dumps(definition,ensure_ascii=False,indent=2)+'\n')
    return len(sections)

counts = {tenant:build(tenant) for tenant in ['itsco','nlu']}
original = OUT/'original-skill-development-manual.txt'
(OUT/'adaptation-notes.json').write_text(json.dumps(dict(
    source='User-supplied Skill Development Training Manual', sourceSha256=hashlib.sha256(original.read_bytes()).hexdigest(),
    date='2026-10-29', sections=counts, evidenceSource='frontend/src/content/learning-support-evidence.json',
    decisions=['ITSCO curriculum framework retained subject to current written group authorization.',
               'NLU permits eligible individual and small-group H2014 within Therapy + Tutoring; groups encouraged, three scheduled preferred, $5 per actual attendee only for groups of two or more, base paid once.',
               'No ISI or generic package edition: this request authorizes ITSCO and NLU programs only.',
               'Facilitator title, scope, diagnosis-targeted approval and licensed oversight preserved.',
               'Coercive participation, forced eye contact, inferred motives, blanket group confidentiality and automatic clinical authorization replaced.',
               'Precepting means observed facilitation and separate competence sign-off, not independent clinical practice.',
               'Research summarized and linked; no copyrighted tools or curricula reproduced, no proprietary program efficacy claimed.',
               'All internal documentation and time use the app. Required emergency calls and external reporting remain necessary.'],
    rollout='Source editions and quizzes prepared locally. Publish through the existing company document workflow; no live publication, billing activation or external AI test in this build.'),ensure_ascii=False,indent=2)+'\n')
print(json.dumps(counts))
